import { test, expect } from '@playwright/test';

test.describe('Keyboard Navigation - Tab Key Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.w3schools.com/html/html_forms.asp');
  });

  test('should navigate through all interactive elements using Tab key', async ({ page }) => {
    // Get all interactive elements that should be focusable
    const interactiveElements = await page.locator('input, button, a[href], select, textarea').all();

    expect(interactiveElements.length).toBeGreaterThan(0);

    // Start by focusing the first element
    await page.keyboard.press('Tab');

    let focusedElement = await page.evaluate(() => {
      return document.activeElement?.tagName;
    });

    expect(focusedElement).toBeTruthy();

    // Tab through multiple elements and verify focus changes
    const focusedElements: string[] = [];

    for (let i = 0; i < 5; i++) {
      const currentFocused = await page.evaluate(() => {
        const element = document.activeElement as HTMLElement;
        return {
          tagName: element?.tagName,
          type: (element as HTMLInputElement)?.type || '',
          text: element?.textContent?.substring(0, 50) || ''
        };
      });

      focusedElements.push(currentFocused.tagName);

      // Verify the focused element is visible
      const isFocusVisible = await page.evaluate(() => {
        const element = document.activeElement as HTMLElement;
        return element && element.offsetParent !== null;
      });

      expect(isFocusVisible).toBe(true);

      // Move to next element
      await page.keyboard.press('Tab');
    }

    // Verify we navigated through different elements
    expect(focusedElements.length).toBeGreaterThan(0);
  });

  test('should navigate backwards through interactive elements using Shift+Tab', async ({ page }) => {
    // Tab forward to get to a focused element
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');

    const forwardFocusedElement = await page.evaluate(() => {
      return (document.activeElement as HTMLElement)?.getAttribute('id') || 
             (document.activeElement as HTMLElement)?.getAttribute('name') ||
             (document.activeElement as HTMLElement)?.tagName;
    });

    // Now shift+tab backwards
    await page.keyboard.press('Shift+Tab');

    const backwardFocusedElement = await page.evaluate(() => {
      return (document.activeElement as HTMLElement)?.getAttribute('id') || 
             (document.activeElement as HTMLElement)?.getAttribute('name') ||
             (document.activeElement as HTMLElement)?.tagName;
    });

    // Elements should be different (we moved backwards)
    expect(backwardFocusedElement).not.toBe(forwardFocusedElement);

    // Verify the element is still visible and focusable
    const isVisible = await page.evaluate(() => {
      const element = document.activeElement as HTMLElement;
      return element && element.offsetParent !== null;
    });

    expect(isVisible).toBe(true);
  });

  test('should maintain focus visibility throughout tab navigation', async ({ page }) => {
    const focusIndicators: boolean[] = [];

    // Tab through 10 elements and check focus visibility
    for (let i = 0; i < 10; i++) {
      await page.keyboard.press('Tab');

      const hasFocusIndicator = await page.evaluate(() => {
        const element = document.activeElement as HTMLElement;
        if (!element) return false;

        const styles = window.getComputedStyle(element);
        const outline = styles.outline;
        const boxShadow = styles.boxShadow;
        const border = styles.border;

        // Check if element has visible focus indicator
        return (
          outline !== 'none' ||
          boxShadow !== 'none' ||
          border !== 'none'
        ) && element.offsetParent !== null;
      });

      focusIndicators.push(hasFocusIndicator);
    }

    // At least some elements should have visible focus indicators
    const elementsWithFocus = focusIndicators.filter(indicator => indicator).length;
    expect(elementsWithFocus).toBeGreaterThan(0);
  });

  test('should skip non-interactive elements during tab navigation', async ({ page }) => {
    const focusedElements: string[] = [];

    // Tab through elements and collect their types
    for (let i = 0; i < 8; i++) {
      await page.keyboard.press('Tab');

      const elementInfo = await page.evaluate(() => {
        const element = document.activeElement as HTMLElement;
        return {
          tagName: element?.tagName,
          isDisabled: (element as HTMLInputElement)?.disabled || false,
          isHidden: element?.offsetParent === null
        };
      });

      // Verify focused element is not disabled or hidden
      expect(elementInfo.isDisabled).toBe(false);
      expect(elementInfo.isHidden).toBe(false);

      focusedElements.push(elementInfo.tagName);
    }

    // All focused elements should be interactive
    const validTags = ['INPUT', 'BUTTON', 'A', 'SELECT', 'TEXTAREA'];
    focusedElements.forEach(tag => {
      expect(validTags).toContain(tag);
    });
  });

  test('should allow interaction with focused elements using keyboard', async ({ page }) => {
    // Navigate to a button
    let foundButton = false;

    for (let i = 0; i < 20; i++) {
      await page.keyboard.press('Tab');

      const currentTag = await page.evaluate(() => {
        return (document.activeElement as HTMLElement)?.tagName;
      });

      if (currentTag === 'BUTTON') {
        foundButton = true;
        break;
      }
    }

    if (foundButton) {
      // Get button text before interaction
      const buttonText = await page.evaluate(() => {
        return (document.activeElement as HTMLElement)?.textContent;
      });

      expect(buttonText).toBeTruthy();

      // Verify button is focused
      const isFocused = await page.evaluate(() => {
        return document.activeElement?.tagName === 'BUTTON';
      });

      expect(isFocused).toBe(true);
    }
  });

  test('should maintain logical tab order across the page', async ({ page }) => {
    const tabOrder: Array<{ tag: string; index: number }> = [];

    // Collect tab order for first 15 tabs
    for (let i = 0; i < 15; i++) {
      await page.keyboard.press('Tab');

      const elementInfo = await page.evaluate(() => {
        const element = document.activeElement as HTMLElement;
        return {
          tag: element?.tagName || 'UNKNOWN',
          position: element?.getBoundingClientRect().top || 0
        };
      });

      tabOrder.push({ tag: elementInfo.tag, index: i });
    }

    // Verify we have a sequence of interactive elements
    expect(tabOrder.length).toBeGreaterThan(5);

    // Verify elements are from expected interactive types
    const validElements = tabOrder.filter(item => 
      ['INPUT', 'BUTTON', 'A', 'SELECT', 'TEXTAREA'].includes(item.tag)
    );

    expect(validElements.length).toBeGreaterThan(0);
  });
});
